from pypdf import PdfReader
from statistics import mean, stdev
r=PdfReader('manuscript.pdf')
urls=set()
for p in r.pages:
 for a in p.get('/Annots',[]):
  obj=a.get_object()
  action=obj.get('/A')
  if action:
   uri=action.get('/URI')
   if uri: urls.add(str(uri))
print('Repository, dataset and artifact links:')
for u in sorted(urls):
 if any(t in u.lower() for t in ('github','zenodo','osf.io','huggingface','dataset','artifact','anonymous')): print(u)
feasible=[]
for a in range(157,161):
 for b in range(a,161):
  for c in range(b,161):
   xs=[a/160,b/160,c/160]
   if mean(xs)>=.995:
    feasible.append((stdev(xs),[a,b,c],mean(xs)))
print('Maximum sample SD for three 160-question runs whose mean rounds to 1.00:', max(feasible))
PY"
